mapper.insert:

    SELECT
        'MLTR'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(MILITARY_NO), LENGTH('MLTR' ) + 1)), 0) + 1, 6, '0')
    FROM MILITARY

INSERT INTO MILITARY (
	MILITARY_NO
	, RESUME_NO
	, SERVICE_CATEGORY_CODE
	, MILITARY_TYPE_CODE
	, MILITARY_RANK_CODE
	, DISCHARGE_CODE
	, MILITARY_START_DATE
	, MILITARY_END_DATE
	, MILITARY_REASON
) VALUES (
	#{militaryNo}
	, #{resumeNo}
	, #{serviceCategoryCode}
	, #{militaryTypeCode}
	, #{militaryRankCode}
	, #{dischargeCode}
	, REPLACE(#{militaryStartDate}, '-', '')
	, REPLACE(#{militaryEndDate}, '-', '')
	, #{militaryReason}
)

mapper.update:
UPDATE MILITARY 
   SET RESUME_NO = #{resumeNo}
   	   , SERVICE_CATEGORY_CODE = #{serviceCategoryCode}
   	   , MILITARY_TYPE_CODE = #{militaryTypeCode}
   	   , MILITARY_RANK_CODE = #{militaryRankCode}
   	   , DISCHARGE_CODE = #{dischargeCode}
   	   , MILITARY_START_DATE = REPLACE(#{militaryStartDate}, '-', '')
   	   , MILITARY_END_DATE = REPLACE(#{militaryEndDate}, '-', '')
   	   , MILITARY_REASON = #{militaryReason} 
 WHERE MILITARY_NO = #{militaryNo}
